/** @param {object} extension @param {*} value */
export function register(extension, value) {
  extension.entryRenderers ??= new Map();
  if (value === undefined) throw new Error("missing value");
}

/** @param {{ packageDir: string }} layout @param {Record<string, string | undefined>} environment */
export function applyPackageLayoutEnvironment(layout, environment = {}) {
  environment.PI_PACKAGE_DIR ??= layout.packageDir;
}
